entry.content:
前言前几天去长三角一带玩了一下，今天总算是整理出来一篇旅行手记了，也和大家分享一下。如果你问我为什么我中考还有时间出来玩，额……你别管我就是有时间怎么滴（逃･*･:≡( ε:)） DAY 1. 2025.6.18 余姚早上我和我爸从武夷山出发，坐火车到杭州东站转车到余姚北，我在火车上还搞了会儿博客(´∀ ˋ) 下午到达余姚北站，先去了我爸到余姚最想去的地方：王阳明故居（我爸就喜欢看这个我有什么办法╮(╯∀╰)╭） var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-121.150000-30.050000',{center:[30.050000,121.150000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['30.050000','121.150000']).addTo(mymap);marker.bindPopup("王阳明故居").openPopup();
晚饭在阳明古街选了一个多小时（为什么都这么贵啊啊）最后将近七点钟终于吃上饭了。 吃完晚饭我们就回酒店啦(ゝ∀･) DAY 2. 2025.6.19 余姚、宁波上午打车去看了河姆渡遗址。 var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-121.350000-29.960000',{center:[29.960000,121.350000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['29.960000','121.350000']).addTo(mymap);marker.bindPopup("河姆渡遗址").openPopup();
河姆渡相比于其他遗址来说还是比较好看的一个啦，至少有房子，有柱子，博物馆也挺好看的，就是外面好热∑(￣□￣;)
然后又去了名人馆。OK又是我不感兴趣的一个，但是跟我爸出来就是这样啦 不过里面说舜是他们那边的人？
下午打车去了我爸这次出来最重要的一个目的地：方太总部。他这次出来主要就是为了来参加方太旗下的一个杭湾书院办的峰会的 var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-121.220000-30.340000',{center:[30.340000,121.220000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['30.340000','121.220000']).addTo(mymap);marker.bindPopup("方太理想城").openPopup();
到了之后已经五点多了，我们先去看了方太的展厅。说实话我对方太的产品不是很感兴趣，主要是设计风格我不太喜欢，黑不溜秋的。不过我在体验冰箱的时候把它们演示用的瓶子打地上了｡ﾟ(ﾟ´ω&#96;ﾟ)ﾟ｡（幸好没碎）（捂脸逃(&#x2F;ω＼)）
在园区里面偶遇小猫~😻
晚上去体验了他们的员工餐（是真难吃）然后入住方太为我们安排的幸福里酒店，挺高档的，大厅里全面全是香水的味道。
我爸说他有一个聚会拉我去参加，那我当然坚持不去啦。我们回酒店房间之后酒店的工作人员把我们的行李送了上来，结果我的硬盘线被她搞断了！ 至于有什么影响吗，嗯……我更不了博客了。我本来还想路上有时间更新一下博客的。为什么我更不了博客了呢？因为我的博客文件在硬盘里面啊。那为什么我不把文件存在电脑里面呢？额……怎么说呢，我家里面有三台电脑，我本来是想我出去带哪台电脑我就把硬盘插到哪台电脑上更博客的，但是事实证明我一般只用一台电脑…… DAY 3 2025.6.20 宁波今天我得跟着我爸去参加杭湾书院的那个峰会呜呜，无聊的要命
午饭是吃的他们杭湾书院的学员出去创业搞得餐馆的盒饭，出乎意料还挺好吃的(≧∀≦)
中午吃完饭有一个义卖活动，我去买了点东西
晚上吃完饭去方太总部转了转，拍了几张照片（多图预警）
DAY 4 2025.6.21 常熟、上海今天可真够忙的，早上吃完饭就从方太的酒店打车去了苏州的常熟，结果把电脑充电线忘在酒店里面了（好好好我在添麻烦这一块是真的优秀•_ゝ•） 我们预约了常熟世界联合学院的探校，我爸说好了要带我来看看的，我好久之前就想来了。中午先去找了我之前的同学吃饭还有YXT吃饭，他最近去希腊了，还看见了支持巴勒斯坦的游行和不知道哪逃出来的难民了呢！(ﾉ&gt;ω&lt;)ﾉ他说他也想跟着游行队伍走的，但是他妈不让。我还一次国没出过呢，我一直劝我爸带我去伦敦东京玩，但是我爸不想去。不过今年8月份我要去一次香港，大家可以等等我去香港的旅行手记哦ლ(╹◡╹ლ) 吃完饭他妈妈带我们去了常熟世界联合学院。这所学校在上海的国际学校家长那里可以说是鼎鼎有名，被誉为 “中国唯一一所真正的国际学校”，我就是从今天见到的那个同学那边知道的。他明年准备考进去，我也是想和他一起进去的，但是据说那所学校超级难进，只有2%的录取率，而且学费很贵，虽然说有助学金啦。我爸就是被我劝来看看这所学校的。 var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-120.740000-31.600000',{center:[31.600000,120.740000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['31.600000','120.740000']).addTo(mymap);marker.bindPopup("常熟世界联合学院").openPopup();
里面整体环境还很不错，很有苏州江南一带的味道，而且他自己就占了一座岛，据说还是市政府给填出来的。反正我看了是觉得很喜欢，我爸那边嘛……我看希望不大_(:3 ⌒ﾞ)_ !教室 看完学校之后我们就打车回上海了（为什么感觉我爸一路上全都是打车走的）上海我也去我也有将近一年没回来了，为什么呢？还不是我爸那该死的开书院的理想…… 我在酒店和我弟汇合了，我妈也是够好玩的，订酒店就定在我们家小区的对面。 我们晚餐是和我哥一起在一家土耳其餐厅吃的，味道还不错，就是吃的东西都不知道是啥，我们还一边吃一边猜这是用啥做的
DAY 5 2025.6.22 上海今天下大雨……然后我又偏偏约了同学出来玩……所以说就很噩梦了(´・ω・&#96;) 早上我刚醒我弟就把手机拿给我说群里面LX已经开始骂我怎么还不起床了，我一看他们怎么七点就开始聊天了。我们约的是10：50到，迟到的人要给每个人买一杯奶茶。 从我家坐地铁过去去静安要一个多小时（上海坐高铁到杭州都只要58分钟）还好12号线不用转车就能到。GZR甚至九点半就到了（这是多不想买奶茶啊……）我那时候还在找地铁口呢。不是GZR九点半商场还没开门呢你去干嘛啊喂(д) ﾟﾟ var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-121.470000-31.240000',{center:[31.240000,121.470000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['31.240000','121.470000']).addTo(mymap);marker.bindPopup("上海静安大悦城").openPopup();
我快到站了才发现我和LX坐的是同一趟地铁。我们是去玩密室逃脱的，这还是我和GZR第一次玩呢。整个感觉其实还行，虽然我和GZR都被抓住了。（人家还是第一次嘛）恐怖还是挺恐怖的，但是幸好有一对情侣和我们一起玩，大哥哥大姐姐人超级好的，一直保护着我。（有一个人可以依赖的感觉真好）ヽ( ^ω^ ゞ ) 我单线任务就没出过几个，有一次我们要拿的东西甚至在NPC手上（不是谁想出来的我下次一定打死他ヽ(#&#96;Д´)ﾉ）。第一次出单线的时候我真的一点头绪都没有，本来想跟对讲机说话的，结果按的时候按成音量键了。到最后那边的工作人员都不耐烦了：“肯定是没有灯的呀，开着灯怎么还有什么难度嘛”ก็ʕ•͡ᴥ•ʔ ก้
下午没什么好说的，LX和GZR要上课，我送他们去那边之后就自己找了个商场看华为和苹果最新出的东西去了。（最近想新买个电脑，如果你们问我现在用的是啥的话，ThinkPad E450……） DAY 6 2025.6.23 上海、杭州今天就主要是陪我爸我妈去处理各种事情，我上午去办了护照和港澳通行证、来往台湾通行证，顺便说一下我是福建户口的，现在只有福建户口可以去跟团去台湾嘻嘻（(∩^o^)⊃━☆ﾟ.*･｡）港澳是8月底就准备去的，外国嘛目前还在跟我爸商量，他对国外的的东西不感兴趣，反正我是可想去了。或者说我可以跟我哥去？今年不是大阪世博会嘛，不知道我哥今年会不会去日本，我是超级想去日本圣地巡礼的ε٩(๑&gt; ₃ &lt;)۶з 下午我们回了一趟我们家（现在出租给别人了）去拿东西，我已经有七年没回来了，谁懂回家的感觉真好，要不是我们家出租给别人了我可以在家宅一周 我们在小区又里面碰到了我们家另一个房子的租客，那个房子之前是我妈当办公室的，我们去年暑假还回去住过，今年好像租给一个法国了。我们碰到的是他的老婆还有儿子，那个小孩长得就像一个洋娃娃一样（不就是洋娃娃吗……(・ω・)）鼻子感觉像是塑料做的（无贬义），据说还是住进我们房子之后才出生的呢！那个人碰到我们还没认出来，还是我妈叫住他的。 然后我们就启程去杭州了。到酒店之后我因为电脑没电了手机又没啥好玩的，居然看起球赛了Σ(°Д°;！我都不敢相信我居然会看球赛。那场比赛好像是女足和哪个国家的球队一场热身赛，讲真的这这几年电视上也就只有比赛好看了，其他的电视台要不就是在播广告要不就是在放电视剧，无聊的要命。呜呜我的电脑啊，你知道对于我来说没有电脑有多难受吗( ´•̥̥̥ω•̥̥̥&#96; ) DAY 7 2025.6.23 杭州今天上午就是在杭州玩，去看了西湖，我们在苏堤上走了一圈。天气有点小雨，不过这样更好，“晴西湖不如雨西湖”嘛(ゝ∀･) var normalm=L.tileLayer.chinaProvider('GaoDe.Normal.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imgm=L.tileLayer.chinaProvider('GaoDe.Satellite.Map',{maxZoom:20,minZoom:1,attribution:'高德地图'});var imga=L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion',{maxZoom:20,minZoom:1,attribution:'高德地图'});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:20,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'});routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1});var normalMap=L.tileLayer.chinaProvider('Google.Normal.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),satelliteMap=L.tileLayer.chinaProvider('Google.Satellite.Map',{maxZoom:21,minZoom:1,attribution:'Google Maps'}),routeMap=L.tileLayer.chinaProvider('Google.Satellite.Annotion',{maxZoom:21,minZoom:1,attribution:'Google Maps'});var normalm1=L.tileLayer.chinaProvider('Geoq.Normal.Map',{maxZoom:21,minZoom:1,attribution:'GeoQ'});var normal=L.layerGroup([normalm]),image=L.layerGroup([imgm,imga]);var baseLayers={"高德地图":normal,"智图地图":normalm1,"谷歌地图":normalMap,"高德卫星地图":imgm,"谷歌卫星地图":satelliteMap,"高德卫星标注":image,"谷歌卫星标注":routeMap};var mymap=L.map('map-120.120000-30.220000',{center:[30.220000,120.120000],zoom:15,layers:[normal],zoomControl:false});L.control.layers(baseLayers,null).addTo(mymap);L.control.zoom({zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(mymap);var marker = L.marker(['30.220000','120.120000']).addTo(mymap);marker.bindPopup("西湖").openPopup();
唯一的问题就是不能骑车上去，我们是骑共享单车到的西湖，高德地图骑车线路里面还有一条“环西湖骑行路线”呢，结果一看，0个人骑过，再一看底下的评论：“整条路一大半都是禁行路段你叫我们怎么骑啊”，笑死我了(^ρ^)&#x2F; 不过有一说一西湖还是超级好看的，不多说了直接上图！
还碰到了小松鼠~ 这次因为时间比较紧，我手里面也没多少钱，所以也没弄条船划划。我看知乎上说在西湖上玩最惬意的方式就是租条船在上面躺一天了，想去哪都可以自己划，下次一定要来试一下( ﾒ∀・) 我们从苏堤上走下来之后本来还想去影视飓风的公司看一下的，但是在网上找了半天都没找到他公司具体在哪个位置，所以说只能不了了之啦ヾ(◎´・ω・｀)ノ 下午就坐火车回武夷山啦~ 至此，本次旅程宣告结束！ 后记这次出去玩我还是很满意的，除了22号那天下雨我鞋都整个泡水里了。密室逃脱那一部分真的特别感谢那两个大哥哥大姐姐，虽然说我们后面是绝对见不到了(._.&#96;) 下次出去玩估计得等8月底了，这会是我人生中第一次出境噢！港澳一定会有很多好玩的，等着我更新哦！

/* Calender */
.card-widget {
    padding: 10px!important;
    max-height: calc(100vh - 100px);
}

.card-times a, .card-times div {
    color: var(--efu-fontcolor);
}

#card-widget-calendar .item-content {
    display: flex;
}

#calendar-area-left {
    width: 45%;
}

#calendar-area-right {
    width: 55%;
}

#calendar-area-left, #calendar-area-right {
    height: 100%;
    padding: 4px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

#calendar-main {
    width: 100%;
}

#calendar-week {
    height: 1.2rem;
    font-size: 14px;
    letter-spacing: 1px;
    font-weight: 700;
    align-items: center;
    display: flex;
}

#calendar-date {
    height: 3rem;
    line-height: 1.3;
    font-size: 64px;
    letter-spacing: 3px;
    color: var(--efu-main);
    font-weight: 700;
    align-items: center;
    display: flex;
    position: absolute;
    top: calc(50% - 2.1rem);
}

#calendar-lunar, #calendar-solar {
    height: 1rem;
    font-size: 12px;
    align-items: center;
    display: flex;
    position: absolute;
}

#calendar-solar {
    bottom: 2.1rem;
}

#calendar-lunar {
    bottom: 1rem;
    color: var(--efu-secondtext);
}

#calendar-main a {
    height: 1rem;
    width: 1rem;
    border-radius: 50%;
    font-size: 12px;
    line-height: 12px;
    display: flex;
    justify-content: center;
    align-items: center;
}

#calendar-main a.now {
    background: var(--efu-main);
    color: var(--efu-card-bg);
}

#calendar-main .calendar-rh a {
    color: var(--efu-secondtext);
}

.calendar-r0, .calendar-r1, .calendar-r2, .calendar-r3, .calendar-r4, .calendar-r5, .calendar-rh {
    height: 1.2rem;
    display: flex;
}

.calendar-d0, .calendar-d1, .calendar-d2, .calendar-d3, .calendar-d4, .calendar-d5, .calendar-d6 {
    width: calc(100% / 7);
    display: flex;
    justify-content: center;
    align-items: center;
}

#card-widget-schedule .item-content {
    display: flex;
}

#schedule-area-left, #schedule-area-right {
    height: 100px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

#schedule-area-left {
    width: 30%;
}

#schedule-area-right {
    width: 70%;
    padding: 0 5px;
}

.schedule-r0, .schedule-r1, .schedule-r2 {
    height: 2rem;
    width: 100%;
    align-items: center;
    display: flex;
}

.schedule-d0 {
    width: 30px;
    margin-right: 5px;
    text-align: center;
    font-size: 12px;
}

.schedule-d1 {
    width: calc(100% - 35px);
    height: 1.5rem;
    align-items: center;
    display: flex;
}

progress::-webkit-progress-bar {
    background: linear-gradient(to right, var(--efu-main-op-deep), var(--efu-main-op), var(--efu-main-op-light));
    border-radius: 5px;
    overflow: hidden;
}

progress::-webkit-progress-value {
    background: var(--efu-main);
    border-radius: 5px;
}

.aside-span1, .aside-span2 {
    height: 1rem;
    font-size: 12px;
    z-index: 1;
    display: flex;
    align-items: center;
    position: absolute;
}

.aside-span1 {
    margin-left: 5px;
}

.aside-span2 {
    right: 20px;
    color: var(--efu-secondtext);
}

.aside-span2 a {
    margin: 0 3px;
}

#pBar_month, #pBar_week, #pBar_year {
    width: 100%;
    border-radius: 5px;
    height: 100%;
}

#schedule-date, #schedule-days, #schedule-title {
    display: flex;
    align-items: center;
}

#schedule-title {
    height: 25px;
    line-height: 1;
    font-size: 14px;
    font-weight: 700;
}

#schedule-days {
    height: 40px;
    line-height: 1;
    font-size: 30px;
    font-weight: 900;
    color: var(--efu-main);
}

#schedule-date {
    height: 20px;
    line-height: 1;
    font-size: 12px;
    color: var(--efu-secondtext);
}
/* History */
#aside-content .card-history .swiper-wrapper {
    flex-direction: column
}

#aside-content .card-history .item-headline {
    margin-left: 0;
}

#aside-content .card-history .history_slide {
    text-align: left;
    display: flex !important;
    flex-direction: column;
    align-items: flex-start
}

#aside-content .card-history .history_slide_time {
    color: var(--efu-secondtext);
    font-size: 14px;
    font-style: italic;
    font-weight: lighter
}

#aside-content .card-history .history_slide_link {
    line-height: 1.5;
    -webkit-line-clamp: 2;
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical
}

#aside-content .card-history .history_slide_link a {
    color: var(--efu-main);
    padding: 0 4px;
    border-radius: 4px
}

#aside-content .card-history .history_slide_link a:hover {
    color: var(--efu-white);
    background: var(--efu-main)
}

